\u0048\u0036\u0044\u006a\u0051\u0053\u002a\u002c\u0025\u0055\u0044\u005d\u0041\u0040\u0023\u0031\u0045\u0054\u002a\u005f\u006f\u0044\u0074\u0073\u0029\u006d\u0054\u0064\u0078\u0031\u002b\u002d\u0058\u006d\u0042\u0055\u005a\u004f\u0067\u0030\u004e\u0023\u004a\u005e\u0073\u0050\u0060\u0048\u005b\u0055\u0056\u0021\u0046\u0061\u0075\u0022\u005b\u0049\u0052\u0074\u0037\u0030\u005b\u002f\u0053\u0069\u007d\u0065\u003b\u0058\u004f\u003d\u005e\u006b\u0036\u006b\u0054\u0070\u003e\u0021\u004d\u0041\u0062\u0027\u0058\u0052\u002e\u007b\u006a\u002c\u0068\u006e\u004c\u0049\u0053\u0058\u0039\u0071\u0038\u0055\u0029\u006d\u003a\u0059\u006c\u004c\u002f\u005d\u0021\u0022\u006c\u0029\u0061\u004f\u0041\u0032\u006a\u0051\u004c\u0049\u0022\u005d\u0065\u0035\u004d\u003e\u0076\u003b\u0028\u0074\u0025\u007c\u0046\u003f\u002b\u0074\u007e\u0075\u0060\u0067\u002e\u0078\u0075\u007a\u0061\u007b\u0024\u0037\u003e\u0022\u005f\u0077\u0050\u006f\u004a\u002f\u003a\u0061\u003f\u004e\u002f\u0059\u0079\u0029\u005d\u0033\u0021\u0023\u0069\u0046\u0023\u0072\u004a\u002d\u0060\u0050\u005a\u0046\u0069\u002c\u0021\u005e\u0078\u002a\u003e\u0065\u0040\u0047\u0053\u005f\u0022\u0028\u0048\u0060\u0053\u0039\u0054\u0032\u003d\u0041\u0022\u0079\u005c\u0021\u002d\u004d\u004e\u002f\u0051\u007d\u005c\u0025\u0042\u004a\u0057\u0061\u0075\u0029\u0065\u0041\u0042\u0069\u0034\u005e\u0040\u0055\u0045\u0076\u006a\u006e\u0023\u004d\u004c\u0045\u002a\u0062\u0034\u0040\u0066\u0076\u005a\u005e\u0030\u006b\u006f\u004d\u006d\u0025\u005e\u0032\u0030\u0031\u0066\u0037\u0059\u0064\u0079\u0051\u005f\u005e\u007a\u006b\u0029\u0068\u0061\u005e\u0043\u0053\u004b\u006e\u0076\u0024\u0024\u0076\u0031\u0071\u004a\u0069\u0022\u0067\u0064\u007c\u006c\u0077\u006b\u0078\u002f\u003a\u0056\u0040\u0045\u002a\u005a\u006a\u0056\u0053\u0031\u0076\u006c\u0048\u002a\u0060\u003b\u0043\u0055\u0071\u003a\u0043\u0033\u007b\u0063\u0026\u002a\u0054\u002c\u0068\u0025\u004d\u002e\u003d\u002b\u0062\u0060\u0021\u006e\u0074\u0029\u006a\u004d\u0039\u0050\u0037\u0043\u0059\u0022\u007d\u0072\u0073\u006a\u0041\u0054\u0058\u0049\u006e\u0030\u003b\u0043\u0071\u003d\u002a\u0047\u003e\u0071\u003e\u0037\u0034\u007b\u0035\u007c\u0048\u003a\u0053\u0053\u0041\u0067\u0073\u004c\u0079\u0066\u007e\u0026\u0072\u006d\u0073\u007a\u007d\u0075\u0074\u005b\u0063\u0071\u006d\u002d\u005a\u005a\u0029\u0025\u002b\u0024\u003a\u0049\u0020\u0076\u0034\u0053\u005d\u0050\u0028\u0051\u0064\u0049\u0039\u0020\u0077\u0061\u0029\u005d\u002f\u0039\u004a\u003b\u0043\u0056\u0023\u005e\u004c\u007d\u0053\u003f\u0070\u0048\u0075\u0033\u002c\u002b\u0028\u0078\u0057\u007b\u0054\u006d\u0021\u0034\u0066\u0061\u0032\u0043\u0034\u005d\u006f\u002b\u0046\u0061\u002f\u0042\u002c\u006a\u007e\u0078\u002a\u0053\u0057\u0050\u0058\u007b\u0040\u0062\u0037\u003f\u004a\u0064\u0033\u005c\u0075\u0075\u0060\u006d\u0076\u004d\u004f\u002f\u0075\u004c\u0029\u0026\u007d\u004c\u0065\u0044\u0024\u0076\u0050\u0048\u0072\u0021\u0030\u0025\u0054\u0076\u0028\u0076\u004e\u007a\u0023\u007c\u0020\u007a\u0070\u0037\u0026\u0027\u006b\u006f\u0035\u0025\u0021\u0050\u0063\u0026\u004c\u007c\u006e\u006c\u0059\u0065\u0032\u004b\u0049\u006f\u0059\u0074\u0025\u0067\u004b\u0051\u0069\u0052\u007a\u0036\u0073\u0023\u005e\u002b\u002b\u006e\u0052\u007a\u0065\u0055\u002a\u005a\u0054\u0079\u003f\u0079\u0037\u005a\u0054\u005a\u0044\u0070\u0040\u0069\u006e\u0079\u003a\u0040\u0064\u007e\u0077\u0059\u0061\u003d\u002b\u004f\u0065\u0061\u0065\u0070\u0068\u0077\u0039\u002d\u0043\u0034\u007b\u0075\u002a\u0022\u0058\u0049\u0079\u0056\u0060\u0028\u002f\u0063\u0037\u005e\u0057\u003b\u0021\u007d\u004e\u0043\u0025\u0024\u003e\u0035\u0067\u0041\u0049\u005b\u005f\u004f\u0042\u0071\u006c\u0025\u004c\u0030\u002e\u002d\u0071\u0058\u0047\u006c\u0035\u005e\u0036\u0065\u0074\u0036\u003e\u007d\u0040\u0029\u003b\u0079\u0039\u004f\u0022\u003b\u0048\u007b\u002b\u0047\u004e\u002e\u0039\u004e\u005c\u004a\u0061\u0026\u004b\u004f\u006d\u0070\u0033\u0035\u002c\u0021\u0061\u0067\u002d\u0059\u007a\u002e\u0069\u0031\u0050\u0056\u0023\u002c\u0023\u002e\u0024\u0068\u0036\u002d\u0041\u0029\u006a\u0021\u0060\u003e\u0078\u003d\u0020\u003d\u0024\u0041\u003b\u0021\u0049\u002d\u0039\u0045\u003a\u0066\u0035\u0071\u006e\u007c\u007d\u0072\u006a\u004b\u0031\u0039\u0065\u007e\u0021\u0030\u002a\u0069\u0049\u007e\u0058\u0069\u0033\u0074\u005c\u0063\u0036\u0023\u004c\u0069\u0078\u0071\u0068\u0042\u004b\u005c\u0042\u0043\u0046\u007a\u006c\u003c\u005b\u0074\u004e\u0062\u003d\u0048\u003a\u0074\u003c\u0077\u004b\u0072\u0048\u005f\u0043\u007c\u0031\u0079\u0043\u003c\u0027\u0045\u0026\u0023\u004b\u0044\u0042\u007d\u0022\u0020\u003a\u0075\u002b\u0054\u0021\u006a\u0066\u0025\u0078\u002c\u004d\u0067\u0060\u0059\u004d\u005d\u002d\u0057\u0047\u004c\u0073\u0038\u0041\u0041\u003f\u0021\u007a\u0023\u0063\u0062\u005a\u0042\u0035\u004f\u002f\u0068\u007a\u0020\u002a\u0049\u0043\u0026\u007a\u0057\u0068\u004c\u005c\u0029\u004b\u005a\u006a\u0072\u007c\u005c\u005a\u0071\u0032\u003c\u0078\u0032\u0057\u0057\u006d\u0051\u0052\u004d\u0029\u007d\u0020\u0057\u0042\u0076\u0040\u007a\u006e\u005e\u005f\u004e\u0044\u0037\u006a\u0058\u0036\u003f\u006d\u0073\u0050\u0037\u0061\u0029\u002c\u0067\u004c\u0051\u007e\u0054\u005b\u0055\u006d\u0044\u004b\u002b\u0061\u005a\u003b\u004d\u0065\u0036\u0070\u0028\u0041\u0061\u006e\u0032\u0043\u0026\u007b\u0028\u0026\u007c\u007a\u0039\u006d\u0022\u0029\u0064\u005b\u002b\u0052\u006d\u002b\u002a\u003b\u0036\u0058\u006d\u006d\u004d\u007d\u002e\u0032\u0042\u005c\u0068\u0046\u0022\u003f\u0071\u0057\u0057\u0076\u0042\u0029\u0027\u0034\u0070\u0054\u0058\u0061\u0041\u0054\u0061\u0075\u0028\u0043\u0067\u0063\u0021\u0064\u006e\u002e\u0059\u0079\u0022\u006e\u003d\u0026\u006d\u0040\u0055\u0075\u0033\u0065\u0027\u004c\u002f\u007d\u0042\u0055\u0033\u0036\u0042\u0043\u004b\u0063\u0063\u004b\u0073\u0040\u0023\u0039\u0029\u0036\u0046\u007e\u0048\u005a\u004d\u0042\u0079\u0029\u0027\u006f\u003e\u005e\u006e\u0050\u0040\u005c\u0035\u004b\u0029\u0052\u0054\u0026\u007d\u0027\u0075\u0052\u0022\u0047\u0051\u0020\u0066\u0031\u003c\u0050\u0041\u0069\u007e\u0050\u006f\u0044\u0027\u0059\u0026\u0036\u002a\u0033\u0073\u006e\u0063\u0047\u0045\u0056\u0061\u0027\u0023\u0039\u0047\u0057\u0028\u006e\u007b\u0059\u0061\u0058\u0067\u0064\u003e\u002d\u004a\u005a\u0032\u007b\u0022\u006f\u0027\u0033\u0030\u0028\u0045\u002b\u0044\u003f\u0029\u002d\u0059\u0053\u007e\u0026\u0072\u0026\u006d\u004e\u0048\u007a\u0056\u003d\u0057\u0060\u0029\u002b\u0040\u0072\u0063\u0069\u0044\u002b\u0028\u0065\u007b\u0039\u0048\u003e\u0071\u0041\u0030\u0032\u0071\u005c\u0078\u003d\u0051\u005c\u0050\u007e\u0031\u0066\u004a\u002d\u0060\u002c\u004d\u003f\u0073\u0042\u0038\u0056\u0039\u0047\u007c\u002a\u002a\u0074\u0067\u003d\u0023\u0060\u002f\u0069\u0042\u0066\u0053\u002e\u0030\u003e\u0050\u0063\u006b\u0073\u0036\u0047\u003b\u0054\u0065\u0044\u004b\u006b\u0064\u0067\u0042\u0069\u0060\u0026\u0055\u0033\u005f\u007a\u0035\u007d\u004f\u0031\u004a\u0023\u0074\u007e\u0043\u0030\u0066\u004f\u0073\u0059\u006c\u003e\u0060\u0065\u0020\u006a\u0029\u0024\u005e\u0049\u004a\u006e\u005c\u0044\u0053\u0042\u005a\u0042\u0022\u0040\u0062\u002d\u0035\u0033\u0062\u0059\u0030\u005e\u007a\u0074\u0073\u0048\u0067\u0042\u0028\u004e\u0052\u0039\u006a\u0077\u002f\u0061\u0065\u0057\u0027\u003d\u0057\u003a\u004a\u0032\u0030\u003b\u0062\u003c\u005f\u0059\u005f\u0075\u0038\u007b\u0041\u0071\u0032\u0042\u0057\u0054\u005a\u0052\u0033\u0034\u004b\u0021\u0064\u0022\u0025\u007b\u0053\u0025\u0036\u004b\u0073\u002e\u0044\u0055\u0068\u0079\u005d\u006a\u0079\u004b\u003d\u0039\u005d\u0062\u0069\u0039\u0074\u006d\u004b\u0055\u0072\u003a\u0049\u0062\u006e\u0041\u0057\u007e\u0038\u005b\u005d\u0076\u002a\u0069\u0043\u005d\u007c\u0075\u0031\u002f\u0022\u004e\u0062\u0052\u0035\u0032\u007e\u005b\u006b\u006c\u0075\u0074\u006c\u004c\u006a\u0042\u0025\u0024\u003b\u0029\u0048\u0041\u0032\u005f\u0031\u0073\u0033\u002d\u0028\u0060\u002f\u0049\u0033\u005a\u0079\u003d\u0040\u002f\u0042\u005a\u0037\u0023\u0026\u0074\u007c\u0030\u007a\u0053\u006a\u0031\u0074\u0067\u0079\u0060\u005a\u004b\u007d\u003b\u0020\u0052\u0056\u0046\u006e\u0049\u0071\u0028\u0044\u006c\u006e\u0063\u002a\u0023\u0045\u0077\u004c\u0059\u006f\u004b\u002d\u007d\u0078\u0045\u002e\u003b\u0021\u003e\u005f\u0044\u004c\u0066\u005c\u002a\u0071\u0027\u0070\u0027\u002e\u0069\u0047\u0047\u0034\u0058\u004f\u0051\u007b\u0027\u0025\u0077\u0035\u0045\u0023\u0032\u002f\u0059\u007e\u005b\u006a\u0077\u0072\u006c\u004d\u0050\u002b\u006c\u005c\u005d\u0078\u007d\u005f\u0030\u007e\u0030\u0073\u002c\u0078\u003c\u0039\u0029\u004e\u0020\u0068\u0069\u0069\u006c\u0030\u002b\u005f\u004e\u0033\u0048\u007b\u0078\u0059\u0040\u0040\u0025\u0038\u0064\u0020\u0059\u0029\u0046\u006e\u004e\u005c\u0069\u0062\u005e\u0035\u0035\u003a\u0029\u002a\u006f\u003c\u0036\u0072\u0065\u0067\u004c\u006f\u0027\u005a\u0065\u0073\u003e\u0062\u002e\u0064\u0064\u0056\u003b\u005b\u0035\u006d\u002d\u003e\u002d\u003f\u0059\u003b\u0024\u0064\u0040\u003b\u006b\u0064\u007c\u0036\u005b\u007e\u0052\u003a\u0074\u003d\u0057\u005b\u002a\u0042\u0055\u002b\u0076\u0031\u002a\u0040\u0037\u005d\u0039\u0038\u003b\u0076\u002d\u0068\u002e\u0050\u0066\u005c\u002a\u0068\u0042\u0050\u0078\u0061\u0029\u003e\u0025\u0038\u003d\u002f\u002b\u0022\u0040\u004f\u0077\u0061\u0020\u005c\u0077\u002b\u0061\u0053\u005a\u0046\u007e\u004e\u0079\u0037\u0041\u0047\u0060\u0053\u0038\u0070\u002b\u0055\u005b\u0055\u0044\u0053\u0062\u0030\u0053\u0049\u0023\u0046\u0077\u0078\u0024\u0059\u002a\u0029\u005b\u002a\u007a\u0020\u0058\u0027\u002f\u0042\u002f\u005d\u0055\u0039\u004e\u0028\u007e\u0022\u002d\u0073\u0052\u0027\u0042\u005b\u006e\u006a\u0079\u0070\u0023\u0024\u005a\u0079\u002d\u003b\u007a\u0065\u0052\u0051\u0040\u0077\u003c\u0031\u0055\u0037\u007a\u007c\u0074\u002c\u0035\u002f\u0068\u007d\u0072\u0062\u005b\u005a\u0035\u0078\u0033\u004a\u0023\u0073\u0049\u006b\u005d\u006e\u004d\u005c\u0051\u0032\u002d\u0070\u0030\u007d\u003f\u006d\u006b\u0024\u006d\u0034\u0047\u0036\u0041\u0041\u006e\u0047\u0063\u002e\u004e\u006d\u0050\u0048\u0067\u0071\u0079\u003b\u0032\u006d\u0054\u004a\u0049\u0021\u0049\u0047\u0030\u0062\u0042\u0033\u0038\u0034\u0034\u0030\u0069\u0026\u0023\u004e\u0043\u0074\u006a\u0079\u0030\u0025\u0041\u004c\u0046\u0032\u0067\u0076\u0024\u004b\u0077\u0068\u0048\u004b\u005f\u0038\u0055\u0077\u0024\u0028\u0068\u006e\u0034\u007d\u0061\u005f\u0040\u006c\u0033\u004e\u007e\u0055\u0028\u004f\u004a\u0062\u0053\u005d\u0025\u004a\u0067\u0035\u005e\u002e\u0045\u0066\u007d\u0029\u0021\u0053\u007a\u0038\u007b\u0026\u0021\u0032\u0057\u0049\u0068\u004c\u002e\u0053\u003f\u006d\u007a\u0064\u005f\u0050\u0035\u0042\u002a\u0048\u0047\u0046\u0028\u003e\u0071\u0029\u0057\u004c\u0069\u0030\u0050\u004c\u0059\u0050\u0032\u0033\u0068\u0041\u0072\u0076\u0050\u0069\u002b\u0058\u0073\u007e\u0073\u0023\u004b\u0025\u006f\u002c\u0059\u0028\u007c\u0022\u0050\u005b\u0079\u0036\u0044\u0052\u0053\u0030\u0024\u0078\u0031\u006b\u005f\u004c\u007e\u0039\u0030\u0048\u0061\u0056\u0023\u002f\u0052\u0037\u006e\u0058\u004e\u004e\u004d\u0075\u005c\u006c\u002f\u0031\u0030\u007c\u0051\u005f\u006e\u0032\u003f\u0029\u0056\u0042\u006e\u0037\u0072\u007e\u006d\u0055\u0079\u005c\u006d\u0053\u0059\u0079\u006d\u0066\u0023\u0034\u002b\u0077\u0060\u0064\u0032\u004a\u004a\u007b\u0063\u0044\u0061\u0039\u005e\u0071\u0050\u004b\u0058\u0079\u0076\u002e\u007b\u0079\u0055\u004f\u002a\u0021\u004a\u003f\u005a\u005a\u0026\u0076\u006e\u0030\u004b\u0035\u0072\u0044\u0074\u0073\u0037\u0020\u006d\u0078\u0058\u006f\u0023\u0078\u0069\u0043\u0040\u0037\u0033\u0029\u007e\u003f\u005f\u006f\u005a\u004c\u004f\u002a\u0043\u0060\u0078\u0076\u005b\u0045\u003b\u0052\u003e\u0045\u002c\u0058\u0021\u0069\u005a\u0078\u004a\u0036\u0038\u0027\u0057\u0025\u0068\u0043\u004e\u0043\u0061\u0076\u0057\u0066\u004d\u004b\u0051\u0026\u0078\u002c\u005c\u0045\u0022\u003b\u0065\u007d\u0045\u0065\u0026\u003a\u0060\u0026\u0059\u002a\u0068\u0072\u0020\u003d\u004d\u0021\u006e\u007e\u0030\u0047\u0049\u003e\u005a\u002c\u0065\u0034\u0074\u007b\u0039\u0048\u005d\u0073\u0034\u0036\u0038\u005a\u0051\u0042\u0069\u005d\u0067\u006e\u0032\u007a\u0058\u0061\u0055